from common14 import *
import re

def write_results(out,data):
    docs=ROOT/'docs/optimization_v2/S14';docs.mkdir(parents=True,exist_ok=True)
    lines=['# S14 核心代码导读','','生产调用链：stepctl → stage14 → runtime14（受检查的 S13 启动适配）→ C++ BT / Python worker → Nav2 / ToolTask → S10 账本与独立安全门。','']
    for rel in ['src/mission_bt.cpp','src/ackermann_planner14.cpp','include/path_retention.hpp','scripts/navigation_config14.py','include/context_clock.hpp','include/collision_volume.hpp','include/slope_observability.hpp','include/local_surface.hpp','tests/local_surface.cpp','include/risk_evidence.hpp','tests/risk_evidence.cpp','scripts/collision_volume14.py','include/decision.hpp','include/tool_permit.hpp','scripts/runtime14.py','scripts/worker14.py','scripts/mission14.py','scripts/admission_recovery14.py','tests/admission_recovery14.py','scripts/budget14.py','scripts/accounting14.py','scripts/ledger_geometry14.py','scripts/ledger14.py','scripts/residual14.py','scripts/analysis14.py','scripts/checkpoint14.py','scripts/regional_math14.py','scripts/regional_localizer14.py','scripts/regional_source14.py','scripts/binding14.py','scripts/routing14.py','tests/build_routes14.py','scripts/regional_occupancy14.py','include/step_reference.hpp','scripts/terrain_source14.py','tests/build_atlas14.py']:
        p=PKG/rel;lines+=['## '+rel,'']
        for i,s in enumerate(p.read_text().splitlines(),1):
            if re.search(r'^\s*(def |class |J choose|BT::NodeStatus (on|update)|void onHalted|inline (bool|void|int|double)|template|int main)',s):lines.append(f'- [{s.strip()}]({p}:{i})')
        lines.append('')
    lines += ['## 按一条实际请求阅读代码', '', '1. `Mission.pulse()` 将定位准入、剩余时间、当前义务和工具状态发到 `/s14/context`；这些值可以与报告决策证据逐项对照。', '2. C++ `Policy.choose()` 先检查失联、安全和预算，再判断等待、重规划或补扫；每次返回结构化 reason_code、输入快照、门限及候选成本。它没有直接发布底盘速度。', '3. `Dispatch::update()` 在动作切换时先发送 CANCEL。Python `Mission.halt()` 取消实际导航并确认工具停止，黑板 idle=true 后 C++ 才发新的编号。`onHalted()` 负责树停止时撤销当前执行。', '4. `Mission.execute_job()` 将喷洒目标变成 NavigateToPose 与 POINT_SERVICE，将割草工作段变成 FollowPath 与 START_WORK。`work_permission()` 和 `toolPermit()` 共同核验工具 key、工作反馈及段类型。', '5. `Mission.collect_tool()` 接收真实 ToolTask 结果；`confirmed_points()` 对成功、数量、重复 key 和不确定状态作检查。覆盖几何采用并集后裁到固定区域，`save()` 同时写任务状态和 residual.geojson。', '6. `residual14.candidate()` 只根据实际残余和原合法作业带提出补扫；`FrozenSchedule` 用于教学及调度模型验证，当前生产 worker 仍按单簇执行，不代表六簇调度已完成。', '7. `analysis14.assess()` 分开判定 C01–C04。短任务达到95%不会改变完整 B1 的分母；冻结图不准入时 C03 必须失败。', '', '先读 `decisions.jsonl` 的 reason_code 和 evidence，再对照 `client/events.jsonl` 中 observation_admission_restored 或 replan_attempt 与实际 Action 返回；最后核对 `client/mission.json` 与 SQLite。观测失联恢复不应被解释成路径受阻重规划。这样可以区分“策略选择了动作”和“动作真的执行并获得反馈”。', '']
    lines+=['导航、工具与融合上游职责：S13 的 execute/revalidate 负责 ROS Action、地图版本、成本地图准入；S10 action_server.cpp 负责工具物理反馈状态机，ledger_core.py 负责反馈配对、幂等事务与有效足迹。S14 只发目标和许可，不直接替换物理反馈。','', 'C++ 条件/联锁例直接测试生产 header；Python 例直接调用生产确认点计数及保留原簇义务的纯账本模型。异步协议测试是真实 BT 进程与测试黑板，不能当成 Gazebo 作业证据。']
    (docs/'CODE_WALKTHROUGH.md').write_text('\n'.join(lines)+'\n')
    result=['# S14 本轮结果','',f"状态：**{data['status']}**；人工：NOT_CHECKED。",'',f"报告：[本轮离线交互报告]({out/'index.html'})",'',f"实际调用：`{' '.join(data.get('command',[]))}`",'', '| 案例 | 作业状态 | 点完成 | 面积完成 m² | 仿真秒 | 停车确认 |','|---|---|---|---|---|---|']
    for name,c in data['cases'].items():
        m=c.get('mission',{});result.append(f"| {name} | {m.get('state','NOT_RUN')} | {m.get('confirmed_points',0)}/{m.get('required_points',0)} | {m.get('confirmed_area_m2',0):.4f}/{m.get('required_area_m2',0):.4f} | {c.get('sim_seconds')} | {c.get('stopped_confirmed')} |")
    result+=['','检查项：`'+json.dumps(data['checks'],ensure_ascii=False)+'`','',data.get('error',''),'',data['next_step_verdict'],'','具体命令/返回码：当前报告目录 commands.jsonl；子进程退出码：各案例 runtime.json。代码/配置/输入哈希、直接前置 S10/S13 回执哈希见 S14/latest.json。报告目录保留原始决策、实际轨迹、SQLite账本及完整残余。','', '已知边界：派生区域地图只验证 A1/B1，尚未推广六簇和连接路；短段、故障正确停车和策略单测不能代替 C03。S13 已存在 Gazebo 关闭 SIGINT 后个别进程 -11 的问题，本轮实际退出码仍原样记录；它不赋予作业成功。']
    result += ['', '## 本机依赖与测试范围', '', '种子41；ROS 2 Jazzy；Gazebo Harmonic。安装版本实测：', '', '```text', (out/'dependency_versions.log').read_text().strip() if (out/'dependency_versions.log').exists() else '未采集', '```', '', 'C++ 决策/工具联锁例、Python 去重与残余例、真实 BT 的异步取消握手、Point32面积传输以及中断时进程清理隔离均以本轮 commands.jsonl 为准。清理测试日志中的 KeyboardInterrupt 为主动注入；不能据此推断生产机器人异常。', '', 'SMOKE 与整簇必须分开：本轮短段即使达到目标，也不改变 A1 的21点或 B1 的16.3594578796 m²。本轮只验收表中实际执行的分支；未触发的补扫/局部绕行与六簇调度不得由单簇成功推定。人工状态仍是 NOT_CHECKED。', '', '区域地图算法和独立测点指标见 TECHNICAL.md；实际整簇结果以本表为准。']
    (docs/'RESULTS.md').write_text('\n'.join(result)+'\n')
